CREATE TABLE "User" ("id" SERIAL NOT NULL, "username" VARCHAR(80) NOT NULL, "password_hash" VARCHAR(255) NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_username_key" ON "User"("username");
CREATE TABLE "products" ("id" SERIAL NOT NULL, "name" VARCHAR(150) NOT NULL, "price" DECIMAL(12,2) NOT NULL, "gst" DECIMAL(5,2) NOT NULL DEFAULT 0, "tax_exempt" BOOLEAN NOT NULL DEFAULT false, "stock" INTEGER NOT NULL DEFAULT 0, "image" VARCHAR(255), "description" TEXT, "sku" VARCHAR(80), "cost" DECIMAL(12,2), "active" BOOLEAN NOT NULL DEFAULT true, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "products_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "products_sku_key" ON "products"("sku"); CREATE INDEX "products_name_idx" ON "products"("name"); CREATE INDEX "products_active_stock_idx" ON "products"("active","stock");
CREATE TABLE "sales" ("id" SERIAL NOT NULL, "subtotal" DECIMAL(12,2), "gst_total" DECIMAL(12,2), "total" DECIMAL(12,2) NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "sale_date" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "cash" DECIMAL(12,2), "change_amount" DECIMAL(12,2), "gst" DECIMAL(5,2) NOT NULL DEFAULT 0, "customer_name" VARCHAR(120), "customer_note" TEXT, "idempotency_key" VARCHAR(100), "imported" BOOLEAN NOT NULL DEFAULT false, CONSTRAINT "sales_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "sales_idempotency_key_key" ON "sales"("idempotency_key"); CREATE INDEX "sales_sale_date_idx" ON "sales"("sale_date"); CREATE INDEX "sales_created_at_idx" ON "sales"("created_at");
CREATE TABLE "sale_items" ("id" SERIAL NOT NULL, "sale_id" INTEGER NOT NULL, "product_id" INTEGER, "product_name" VARCHAR(150) NOT NULL, "product_name_inferred" BOOLEAN NOT NULL DEFAULT false, "tax_exempt" BOOLEAN NOT NULL DEFAULT false, "qty" INTEGER NOT NULL, "price" DECIMAL(12,2) NOT NULL, "gst" DECIMAL(12,2) NOT NULL DEFAULT 0, "subtotal" DECIMAL(12,2) NOT NULL, "discount" DECIMAL(12,2) NOT NULL DEFAULT 0, "gst_rate" DECIMAL(5,2) NOT NULL DEFAULT 0, CONSTRAINT "sale_items_pkey" PRIMARY KEY ("id"));
CREATE INDEX "sale_items_sale_id_idx" ON "sale_items"("sale_id"); ALTER TABLE "sale_items" ADD CONSTRAINT "sale_items_sale_id_fkey" FOREIGN KEY ("sale_id") REFERENCES "sales"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "sale_items" ADD CONSTRAINT "sale_items_product_id_fkey" FOREIGN KEY ("product_id") REFERENCES "products"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE TABLE "inventory_adjustments" ("id" SERIAL NOT NULL, "product_id" INTEGER NOT NULL, "delta" INTEGER NOT NULL, "reason" VARCHAR(240) NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "inventory_adjustments_pkey" PRIMARY KEY ("id")); CREATE INDEX "inventory_adjustments_product_id_created_at_idx" ON "inventory_adjustments"("product_id","created_at"); ALTER TABLE "inventory_adjustments" ADD CONSTRAINT "inventory_adjustments_product_id_fkey" FOREIGN KEY ("product_id") REFERENCES "products"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "cash_drawer" ("id" SERIAL NOT NULL, "opening" DECIMAL(12,2), "closing" DECIMAL(12,2), "expected" DECIMAL(12,2), "difference" DECIMAL(12,2), "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "cash_drawer_pkey" PRIMARY KEY ("id"));
CREATE TABLE "end_of_day" ("id" SERIAL NOT NULL, "report_date" DATE, "total_sales" DECIMAL(12,2), "cash_received" DECIMAL(12,2), "expected_cash" DECIMAL(12,2), "actual_cash" DECIMAL(12,2), "float_amount" DECIMAL(12,2), "difference" DECIMAL(12,2), "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "end_of_day_pkey" PRIMARY KEY ("id")); CREATE INDEX "end_of_day_report_date_idx" ON "end_of_day"("report_date");
